class Solution {
 int removePairs(string& s,char a,char b,int points){
  string st;int score=0;
  for(char c:s){if(!st.empty() && st.back()==a && c==b){st.pop_back();score+=points;}else st.push_back(c);}
  s.swap(st);return score;
 }
public:
 int maximumGain(string s,int x,int y){
  if(x>=y)return removePairs(s,'a','b',x)+removePairs(s,'b','a',y);
  return removePairs(s,'b','a',y)+removePairs(s,'a','b',x);
 }
};
